---@class ECSGroupManager
local ECSGroupManager = Class("ECSGroupManager")

local XLuaUtils = CS.Engine.Lib.XLuaUtils

local ECSGroup = import("Frame.ECS.ECSGroup")

function ECSGroupManager:__init(world)
    self.world = world
    self.allGroups = {}
    self.groupsList = {}
    self.entityToGroup = {} -- entityId:groups
    self.groupToEntity = {} -- groupId:entities


end

---StringArrayToInt
---@param array table
function ECSGroupManager:StringArrayToInt(array)
    quick_sort_DESC(array, 0, #array)
    local tempS = table.concat(array, "&")
    return XLuaUtils.ToHash(tempS)
end

---GetEntityByKeyFilters
---@param key table
---@param filters table
function ECSGroupManager:GetEntityByKeyFilters(key, filters)
    local group = self.allGroups[checkString(key)]
    if isNull(group) then
        --添加组
        self:__AddGroup(key, filters)
        group = self.allGroups[checkString(key)]
    end
    local entities = self.groupToEntity[group.key]
    if isNull(entities) then
        entities = {}
    end
    return entities
end

function ECSGroupManager:GetEntityByFilters(filters)
    local key = self:StringArrayToInt(filters)
    return self:GetEntityByKeyFilters(key, filters)
end

function ECSGroupManager:__AddGroup(key, filters)
    if isNull(filters) then
        printError("AddGroup 失败，参数不能为空")
        return false
    end
    if self.allGroups[checkString(key)] then
        printError("AddGroup 失败，名字重复")
        return false
    end
    local group = ECSGroup.New(key, filters, self.world)
    self.allGroups[checkString(key)] = group
    table.insert(self.groupsList, group)
    local entityList = {}
    if table.count(self.entityToGroup) > 0 then
        for entityId, v in pairs(self.entityToGroup) do
            local entity = self.world:GetEntity(entityId)
            local isContains = true
            table.walk(filters, function(key, value)
                if not entity:IsCompExistsByName(value) then
                    isContains = false
                end
            end)
            if isContains then
                table.insert(entityList, entity)
                self.entityToGroup[tostring(entityId)] = group
            end
        end
    end
    self.groupToEntity[checkString(key)] = entityList
    return true
end

---OnEntityDestroy
---@param entity ECSEntity
function ECSGroupManager:OnEntityDestroy(entity)
    local id = entity:ID()
    local groups = self.entityToGroup[checkString(id)]
    if isTable(groups) then
        for i = 1, #groups do
            local datas = self.groupToEntity[checkString(groups[i])]
            for i = 1, table.length(datas) do
                if datas[i]:ID() == id then
                    table.remove(datas, i)
                end
            end
        end
    end
    self.entityToGroup[checkString(id)] = {}
end

return ECSGroupManager